def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider separating two equally sized panels.
    split = None
    for r in range(h):
        color = grid[r][0]
        if all(x == color for x in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            if top and bottom and len(top) == len(bottom):
                split = ("h", r, top, bottom)
                break

    if split is None:
        for c in range(w):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(h)):
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                if c and len(left[0]) == len(right[0]):
                    split = ("v", c, left, right)
                    break

    if split is None:
        return grid

    _, _, first, second = split
    shared = set(x for row in first for x in row) & set(x for row in second for x in row)
    fill = min(shared)

    return [
        [3 if first[r][c] == second[r][c] else fill
         for c in range(len(first[0]))]
        for r in range(len(first))
    ]
